7	Test test_a2_local_mix("a2.local.mix", []() {
8		RNG rng(2266524198);
9	
10		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 2));
11	
12		constexpr uint32_t operations = 10;
13	
14		// On a list iterator, std::advance is O(n), making this O(n^2).
15		// It would be nice if we had a halfedge mesh implementation with flat arrays instead of std::lists...
16		auto vertex = [&]() {
17			int32_t idx = rng.integer(0, static_cast<int32_t>(mesh.vertices.size()));
18			auto itr = mesh.vertices.begin();
19			std::advance(itr, idx);
20			return itr;
21		};
