std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::bisect_edge(EdgeRef e) {
	HalfedgeRef h = e->halfedge;   //h : v1 -> v2
	HalfedgeRef t = h->twin;       //t : v2 -> v1
	HalfedgeRef hn = h->next;
	HalfedgeRef tn = t->next;
	VertexRef v1 = h->vertex;
	VertexRef v2 = t->vertex;

	//new elements: one vertex, two halfedges, one edge:
	VertexRef m = emplace_vertex();
	HalfedgeRef h2 = emplace_halfedge(); //h2 : m -> v2 (new edge)
	HalfedgeRef t2 = emplace_halfedge(); //t2 : m -> v1 (on e)
	EdgeRef e2 = emplace_edge(e->sharp);

	//data:
	m->position = e->center();
	interpolate_data({v1, v2}, m);
	interpolate_data({h, hn}, h2); //dividing h -> (h, h2)
	interpolate_data({t, tn}, t2); //dividing t -> (t, t2)

	//connectivity: h stays on e and becomes v1 -> m, t becomes v2 -> m and
	// moves to the new edge e2:
	h->twin = t2;
	h->next = h2;
	h2->set_tnvef(t, hn, m, e2, h->face);
	t->twin = h2;
	t->next = t2;
	t->edge = e2;
	t2->set_tnvef(h, tn, m, e, t->face);

	e->halfedge = h;
	e2->halfedge = h2;
	m->halfedge = h2;
	//v1->halfedge and v2->halfedge still reference h and t, which still
	// leave v1 and v2 respectively, so they remain valid.

	return m;
}

std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::split_edge(EdgeRef e) {
	// A2L2 (REQUIRED): split_edge

	//first, bisect the edge:
	std::optional<VertexRef> opt_m = bisect_edge(e);
	if (!opt_m) return std::nullopt;
	VertexRef m = *opt_m;

	//after bisection:
	HalfedgeRef h = e->halfedge; //h  : v1 -> m  (on e)
	HalfedgeRef t2 = h->twin;    //t2 : m  -> v1 (on e)
	HalfedgeRef h2 = h->next;    //h2 : m  -> v2 (on the bisected-off edge)
	HalfedgeRef t = h2->twin;    //t  : v2 -> m  (on the bisected-off edge)

	//split h's face (unless boundary) by connecting m to the vertex ccw from
	// v2 (the ccw-most end of e within the face):
	if (!h->face->boundary) {
		FaceRef f = h->face;
		HalfedgeRef hn = h2->next; //hn : v2 -> c
		HalfedgeRef hc = hn->next; //hc : c -> ...
		VertexRef c = hc->vertex;
		HalfedgeRef hcn = hc->next;

		FaceRef f2 = emplace_face(false);    //will become {m, v2, c}
		HalfedgeRef d = emplace_halfedge();  //d  : m -> c (in f)
		HalfedgeRef dt = emplace_halfedge(); //dt : c -> m (in f2)
		EdgeRef de = emplace_edge(false);

		d->set_tnvef(dt, hc, m, de, f);
		dt->set_tnvef(d, h2, c, de, f2);
		de->halfedge = d;

		h->next = d;
		hn->next = dt;

		h2->face = f2;
		hn->face = f2;
		f2->halfedge = h2;
		f->halfedge = h;

		interpolate_data({h, h2}, d);
		interpolate_data({hc, hcn}, dt);
	}

	//split t's face (unless boundary) by connecting m to the vertex ccw from
	// v1 (the ccw-most end of e within that face):
	if (!t->face->boundary) {
		FaceRef g = t->face;
		HalfedgeRef tn = t2->next; //tn : v1 -> c'
		HalfedgeRef tc = tn->next; //tc : c' -> ...
		VertexRef c2 = tc->vertex;
		HalfedgeRef tcn = tc->next;

		FaceRef g2 = emplace_face(false);    //will become {m, v1, c'}
		HalfedgeRef d = emplace_halfedge();  //d  : m -> c' (in g)
		HalfedgeRef dt = emplace_halfedge(); //dt : c' -> m (in g2)
		EdgeRef de = emplace_edge(false);

		d->set_tnvef(dt, tc, m, de, g);
		dt->set_tnvef(d, t2, c2, de, g2);
		de->halfedge = d;

		t->next = d;
		tn->next = dt;

		t2->face = g2;
		tn->face = g2;
		g2->halfedge = t2;
		g->halfedge = t;

		interpolate_data({t, t2}, d);
		interpolate_data({tc, tcn}, dt);
	}

	//the new vertex's halfedge should lie along the original edge:
	m->halfedge = t2;

	return m;
}

