std::optional<Halfedge_Mesh::FaceRef> Halfedge_Mesh::extrude_face(FaceRef f) {
	//A2L4: Extrude Face
	// Reminder: This function does not update the vertex positions.
	// Remember to also fill in extrude_helper (A2L4h)

	//collect the face's halfedges / vertices (ccw around f):
	std::vector<HalfedgeRef> hs;
	std::vector<VertexRef> vs;
	{
		HalfedgeRef h = f->halfedge;
		do {
			hs.push_back(h);
			vs.push_back(h->vertex);
			h = h->next;
		} while (h != f->halfedge);
	}
	uint32_t n = static_cast<uint32_t>(hs.size());

	//per original halfedge: one new vertex, one inner edge, one spoke edge,
	// four halfedges, and one quad side face:
	std::vector<VertexRef> nvs(n);   //nvs[i]: inset copy of vs[i]
	std::vector<HalfedgeRef> ih(n);  //ih[i] : v_i' -> v_j' (on f)
	std::vector<HalfedgeRef> iht(n); //iht[i]: v_j' -> v_i' (on quad i)
	std::vector<HalfedgeRef> sp(n);  //sp[i] : v_i  -> v_i' (on quad i-1)
	std::vector<HalfedgeRef> spt(n); //spt[i]: v_i' -> v_i  (on quad i)
	std::vector<EdgeRef> ie(n), se(n);
	std::vector<FaceRef> quads(n);

	for (uint32_t i = 0; i < n; ++i) {
		nvs[i] = emplace_vertex();
		//new vertices start at the same positions as the originals
		// (see [BEVEL NOTE]); extrude_positions() moves them later:
		nvs[i]->position = vs[i]->position;
		interpolate_data({vs[i]}, nvs[i]);

		ih[i] = emplace_halfedge();
		iht[i] = emplace_halfedge();
		sp[i] = emplace_halfedge();
		spt[i] = emplace_halfedge();
		ie[i] = emplace_edge(false);
		se[i] = emplace_edge(false);
		quads[i] = emplace_face(false);
	}

	for (uint32_t i = 0; i < n; ++i) {
		uint32_t j = (i + 1) % n;

		//quad i is [v_i, v_j, v_j', v_i']; it absorbs the original halfedge hs[i]:
		hs[i]->next = sp[j];
		hs[i]->face = quads[i];
		sp[j]->set_tnvef(spt[j], iht[i], vs[j], se[j], quads[i]);
		iht[i]->set_tnvef(ih[i], spt[i], nvs[j], ie[i], quads[i]);
		spt[i]->set_tnvef(sp[i], hs[i], nvs[i], se[i], quads[i]);
		quads[i]->halfedge = hs[i];

		//f becomes the inner face, edged by the ih[i] cycle:
		ih[i]->set_tnvef(iht[i], ih[j], nvs[i], ie[i], f);

		ie[i]->halfedge = ih[i];
		se[i]->halfedge = sp[i];
		nvs[i]->halfedge = ih[i];
		//vs[i]->halfedge remains valid since hs[i] still leaves vs[i].

		//corner data for new halfedges comes from the matching original corner:
		interpolate_data({hs[i]}, ih[i]);  //corner at v_i'
		interpolate_data({hs[j]}, iht[i]); //corner at v_j'
		interpolate_data({hs[i]}, sp[i]);  //corner at v_i
		interpolate_data({hs[i]}, spt[i]); //corner at v_i'
	}
	f->halfedge = ih[0];

	return f;
}

