std::optional<Halfedge_Mesh::EdgeRef> Halfedge_Mesh::flip_edge(EdgeRef e) {
	//A2L1: Flip Edge - works for general polygon faces

	HalfedgeRef h = e->halfedge;   //h : a -> b (in f)
	HalfedgeRef t = h->twin;       //t : b -> a (in g)
	FaceRef f = h->face;
	FaceRef g = t->face;

	//cannot flip an edge on the boundary:
	if (f->boundary || g->boundary) return std::nullopt;

	VertexRef a = h->vertex;
	VertexRef b = t->vertex;
	HalfedgeRef hb = h->next;  //hb : b -> c
	HalfedgeRef hc = hb->next; //hc : c -> ...
	HalfedgeRef ta = t->next;  //ta : a -> d
	HalfedgeRef td = ta->next; //td : d -> ...
	VertexRef c = hc->vertex;
	VertexRef d = td->vertex;

	//halfedges before h and t in their faces:
	HalfedgeRef hp = hc;
	while (hp->next != h) hp = hp->next;
	HalfedgeRef tp = td;
	while (tp->next != t) tp = tp->next;

	//--- validity checks ---
	//rotating ccw, the edge would connect c and d:
	if (c == d) return std::nullopt;
	//d must not already be a vertex of f (f would touch d twice), and
	// c must not already be a vertex of g:
	{
		HalfedgeRef x = f->halfedge;
		do {
			if (x->vertex == d) return std::nullopt;
			x = x->next;
		} while (x != f->halfedge);
		x = g->halfedge;
		do {
			if (x->vertex == c) return std::nullopt;
			x = x->next;
		} while (x != g->halfedge);
	}
	//c and d must not already be connected by an edge (non-manifold result):
	{
		HalfedgeRef x = c->halfedge;
		do {
			if (x->twin->vertex == d) return std::nullopt;
			x = x->twin->next;
		} while (x != c->halfedge);
	}

	//--- rewire (no elements are created or destroyed) ---
	//h becomes d -> c and stays in f; t becomes c -> d and stays in g.
	//f' runs c -> ... -> a -> d -> c (old chain, then ta, then h);
	//g' runs d -> ... -> b -> c -> d (old chain, then hb, then t):
	hp->next = ta;
	ta->next = h;
	h->next = hc;
	h->vertex = d;

	tp->next = hb;
	hb->next = t;
	t->next = td;
	t->vertex = c;

	ta->face = f;
	hb->face = g;

	//fix halfedge pointers of the elements whose halfedge moved or was
	// reassigned:
	if (f->halfedge == hb) f->halfedge = h;
	if (g->halfedge == ta) g->halfedge = t;
	if (a->halfedge == h) a->halfedge = ta;
	if (b->halfedge == t) b->halfedge = hb;

	return e;
}

