std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::collapse_edge(EdgeRef e) {
	//A2L3: Collapse Edge - general polygon version

	HalfedgeRef h = e->halfedge;   //h : a -> b (in f)
	HalfedgeRef t = h->twin;       //t : b -> a (in g)
	VertexRef a = h->vertex;       //survives as the merged vertex
	VertexRef b = t->vertex;       //is erased
	FaceRef f = h->face;
	FaceRef g = t->face;
	HalfedgeRef hn = h->next;
	HalfedgeRef tn = t->next;

	//a boundary triangle would become a 2-gon:
	if (f->boundary && f->degree() == 3) return std::nullopt;
	if (g->boundary && g->degree() == 3) return std::nullopt;

	//an interior edge whose endpoints are both on the boundary would pinch
	// the boundary into itself:
	if (!f->boundary && !g->boundary && a->on_boundary() && b->on_boundary()) return std::nullopt;

	bool f_tri = !f->boundary && f->degree() == 3;
	bool g_tri = !g->boundary && g->degree() == 3;
	VertexRef cf = hn->next->vertex; //vertex ccw from b in f
	VertexRef cg = tn->next->vertex; //vertex ccw from a in g
	if (f_tri && g_tri && cf == cg) return std::nullopt; //two-triangle "fin"

	//collect outgoing halfedges of a and b before any rewiring:
	std::vector<HalfedgeRef> a_out, b_out;
	{
		HalfedgeRef x = a->halfedge;
		do {
			a_out.push_back(x);
			x = x->twin->next;
		} while (x != a->halfedge);
		x = b->halfedge;
		do {
			b_out.push_back(x);
			x = x->twin->next;
		} while (x != b->halfedge);
	}

	//link condition: any vertex adjacent to both a and b must be the vertex
	// opposite e in a triangle adjacent to e (its two edges to a and b get
	// merged by the collapse instead of becoming duplicate edges):
	{
		std::unordered_set<VertexRef> neighbors_of_a;
		for (HalfedgeRef x : a_out) neighbors_of_a.insert(x->twin->vertex);
		for (HalfedgeRef x : b_out) {
			VertexRef w = x->twin->vertex;
			if (w == a || w == b) continue;
			if (!neighbors_of_a.count(w)) continue;
			if (!((f_tri && w == cf) || (g_tri && w == cg))) return std::nullopt;
		}
	}

	//no face other than f and g may touch both a and b (such a face would
	// touch the merged vertex twice):
	for (HalfedgeRef x : a_out) {
		FaceRef k = x->face;
		if (k == f || k == g) continue;
		HalfedgeRef y = k->halfedge;
		do {
			if (y->vertex == b) return std::nullopt;
			y = y->next;
		} while (y != k->halfedge);
	}

	//--- perform the collapse ---
	//the merged vertex lands at the midpoint of the edge:
	Vec3 mid = e->center();
	interpolate_data({a, b}, a);
	a->position = mid;

	HalfedgeRef a_he; //a surviving halfedge leaving a, for a->halfedge

	if (f_tri) {
		//f degenerates; its other two edges are merged into e1:
		HalfedgeRef h1 = hn;        //h1 : b  -> cf
		HalfedgeRef h2 = hn->next;  //h2 : cf -> a
		HalfedgeRef h1t = h1->twin; //h1t: cf -> b  (survives as cf -> m)
		HalfedgeRef h2t = h2->twin; //h2t: a  -> cf (survives as m  -> cf)
		EdgeRef e1 = h1->edge;
		EdgeRef e2 = h2->edge;

		interpolate_data({h1t, h2}, h1t); //merged cf -> m corner
		interpolate_data({h2t, h1}, h2t); //merged m -> cf corner

		h1t->twin = h2t;
		h2t->twin = h1t;
		h1t->edge = e1;
		h2t->edge = e1;
		e1->halfedge = h1t;
		cf->halfedge = h1t;

		erase_halfedge(h);
		erase_halfedge(h1);
		erase_halfedge(h2);
		erase_edge(e2);
		erase_face(f);
	} else {
		//f just loses h:
		HalfedgeRef hp = hn;
		while (hp->next != h) hp = hp->next;
		hp->next = hn;
		if (f->halfedge == h) f->halfedge = hn;
		erase_halfedge(h);
	}

	if (g_tri) {
		//g degenerates; its other two edges are merged into ge1:
		HalfedgeRef g1 = tn;        //g1 : a  -> cg
		HalfedgeRef g2 = tn->next;  //g2 : cg -> b
		HalfedgeRef g1t = g1->twin; //g1t: cg -> a  (survives as cg -> m)
		HalfedgeRef g2t = g2->twin; //g2t: b  -> cg (survives as m  -> cg)
		EdgeRef ge1 = g1->edge;
		EdgeRef ge2 = g2->edge;

		interpolate_data({g1t, g2}, g1t); //merged cg -> m corner
		interpolate_data({g2t, g1}, g2t); //merged m -> cg corner

		g1t->twin = g2t;
		g2t->twin = g1t;
		g1t->edge = ge1;
		g2t->edge = ge1;
		ge1->halfedge = g1t;
		cg->halfedge = g1t;

		erase_halfedge(t);
		erase_halfedge(g1);
		erase_halfedge(g2);
		erase_edge(ge2);
		erase_face(g);

		a_he = g2t; //survives; reassigned to a below
	} else {
		//g just loses t:
		HalfedgeRef tp = tn;
		while (tp->next != t) tp = tp->next;
		tp->next = tn;
		if (g->halfedge == t) g->halfedge = tn;
		erase_halfedge(t);

		a_he = tn; //survives and leaves a
	}

	//b's remaining outgoing halfedges now leave a (erased halfedges have
	// their vertex set to vertices.end() and are skipped):
	for (HalfedgeRef x : b_out) {
		if (x->vertex == b) x->vertex = a;
	}
	a->halfedge = a_he;

	erase_vertex(b);
	erase_edge(e);

	return a;
}

