args.new_string:
void Halfedge_Mesh::extrude_positions(FaceRef face, Vec3 move, float shrink) {
	//A2L4h: Extrude Positions Helper

	//'face' is the inner face created by extrude_face. For an inner halfedge
	// h : v_i' -> v_j', h->twin lies on the side quad, h->twin->next is the
	// spoke v_i' -> v_i, and its twin starts at the original vertex v_i --
	// which still sits at the position v_i' started from.

	//centroid of the original (outer) ring of vertices:
	Vec3 centroid;
	float n = 0.0f;
	{
		HalfedgeRef h = face->halfedge;
		do {
			centroid += h->twin->next->twin->vertex->position;
			n += 1.0f;
			h = h->next;
		} while (h != face->halfedge);
		centroid /= n;
	}

	//lerp each inner vertex from its original position toward the centroid
	// by 'shrink', then translate by 'move':
	HalfedgeRef h = face->halfedge;
	do {
		Vec3 orig = h->twin->next->twin->vertex->position;
		h->vertex->position = orig + shrink * (centroid - orig) + move;
		h = h->next;
	} while (h != face->halfedge);
}

